pub const NextArgCase = struct {
    name: []const u8,
    input: []const u8,
    expected_param: []const u8,
    expected_value: ?[]const u8,
    expected_rest: []const u8,
};

pub const next_arg_cases = [_]NextArgCase{
    .{
        .name = "quoted value with trailing token",
        .input = "root=\"/dev/sda 1\" ro",
        .expected_param = "root",
        .expected_value = "/dev/sda 1",
        .expected_rest = "ro",
    },
    .{
        .name = "quoted value keeps embedded equals inside the value",
        .input = "mode=\"fast=boot\" next",
        .expected_param = "mode",
        .expected_value = "fast=boot",
        .expected_rest = "next",
    },
    .{
        .name = "quoted bare token with trailing token",
        .input = "\"noparam value\" next",
        .expected_param = "noparam value",
        .expected_value = null,
        .expected_rest = "next",
    },
    .{
        .name = "empty quoted bare token stays empty and unsplit",
        .input = "\"\" next",
        .expected_param = "",
        .expected_value = null,
        .expected_rest = "next",
    },
    .{
        .name = "leading quoted token with equals splits like Linux",
        .input = "\"key=value\" next",
        .expected_param = "key",
        .expected_value = "value",
        .expected_rest = "next",
    },
    .{
        .name = "unquoted value keeps punctuation until whitespace",
        .input = "console=ttyS0,115200n8 panic=-1",
        .expected_param = "console",
        .expected_value = "ttyS0,115200n8",
        .expected_rest = "panic=-1",
    },
    .{
        .name = "empty quoted value becomes empty string",
        .input = "rdinit=\"\" quiet",
        .expected_param = "rdinit",
        .expected_value = "",
        .expected_rest = "quiet",
    },
    .{
        .name = "empty whitespace-separated value stays on the current token",
        .input = "foo= bar",
        .expected_param = "foo",
        .expected_value = "",
        .expected_rest = "bar",
    },
    .{
        .name = "first equals wins inside the value",
        .input = "key=alpha=beta tail",
        .expected_param = "key",
        .expected_value = "alpha=beta",
        .expected_rest = "tail",
    },
    .{
        .name = "quoted value without trailing token leaves empty rest",
        .input = "mode=\"fast boot\"",
        .expected_param = "mode",
        .expected_value = "fast boot",
        .expected_rest = "",
    },
    .{
        .name = "unterminated quoted value consumes the token tail",
        .input = "key=\"alpha beta",
        .expected_param = "key",
        .expected_value = "alpha beta",
        .expected_rest = "",
    },
    .{
        .name = "trailing spaces after key=value trim to empty rest",
        .input = "root=/dev/sda1 \t\nro",
        .expected_param = "root",
        .expected_value = "/dev/sda1",
        .expected_rest = "ro",
    },
    .{
        .name = "leading equals sign stays in the parameter token",
        .input = "=bad next",
        .expected_param = "=bad",
        .expected_value = null,
        .expected_rest = "next",
    },
};
